const topicPictures=new Map();
async function ensureTopicPictures(topic){if(!topic)return;if(!topicPictures.has(topic.code)){topicPictures.set(topic.code,preparePictures(topic.entries,()=>{},{bundlePath:topic.bundle,cacheName:'little-objects-lesson-'+topic.code}).catch(e=>{topicPictures.delete(topic.code);throw e;}));}await topicPictures.get(topic.code);}
