function bindLesson(){const form=$('#lesson-form');if(!form)return;form.onsubmit=async event=>{event.preventDefault();const topic=findTopic(topics,$('#lesson-code').value);if(!topic){$('#lesson-error').textContent='That lesson code was not found. Check the number with your teacher.';return;}const button=form.querySelector('button');button.disabled=true;$('#lesson-error').textContent='Getting lesson pictures ready…';try{await ensureTopicPictures(topic);profile.settings.lessonCode=topic.code;await put('profiles',profile);await home();if(topic.code==='67')toast('Secret level unlocked. +67 aura. No cap.');}catch{$('#lesson-error').textContent='The lesson could not load. Check your connection and try again.';button.disabled=false;}};const leave=$('#leave-lesson');if(leave)leave.onclick=async()=>{profile.settings.lessonCode='';await put('profiles',profile);await home();};}
