async function navigate(next){if(current&&view!=='summary'&&['learn','guess','memo','check','sentences','mixed','explore'].includes(view)){await finishSession(false);if(next==='home')return;}teardown();view=next;if(next==='home')await home();if(next==='settings')settings();if(next==='progress')await progress();window.scrollTo(0,0);}
const icons={explore:'<svg viewBox="0 0 50 50"><circle cx="22" cy="21" r="15" fill="#f4df9a" stroke="#436d53" stroke-width="2"/><path d="m33 33 12 12M16 21h12m-6-6v12" stroke="#436d53" stroke-width="3"/></svg>',mixed:'<svg viewBox="0 0 50 50"><rect x="4" y="5" width="19" height="19" rx="5" fill="#c8bde6"/><circle cx="36" cy="15" r="10" fill="#b8d9e0"/><path d="M7 39h35m-8-7 8 7-8 7" stroke="#436d53" stroke-width="3" fill="none"/></svg>',sentences:'<svg viewBox="0 0 50 50"><rect x="5" y="8" width="40" height="31" rx="8" fill="#b8d9e0"/><path d="M15 39v7l9-7" fill="#b8d9e0"/><path d="M13 20h24M13 27h17" stroke="#436d53" stroke-width="2"/></svg>',learn:'<svg viewBox="0 0 50 50" fill="none"><rect x="7" y="10" width="28" height="33" rx="7" fill="#aec782" transform="rotate(-12 7 10)"/><rect x="18" y="5" width="27" height="34" rx="7" fill="#fffdf2" stroke="#436d53" stroke-width="1.7"/><path d="M26 17h11M26 23h8M26 29h11" stroke="#436d53" stroke-width="2" stroke-linecap="round"/></svg>',guess:'<svg viewBox="0 0 50 50" fill="none"><rect x="4" y="4" width="18" height="18" rx="5" fill="#f1d2b4"/><rect x="27" y="4" width="18" height="18" rx="5" fill="#f1d2b4"/><rect x="4" y="27" width="18" height="18" rx="5" fill="#f1d2b4"/><rect x="27" y="27" width="18" height="18" rx="5" fill="#d7e3ba"/><path d="m31 36 4 4 7-8" stroke="#436d53" stroke-width="2" stroke-linecap="round"/></svg>',memo:'<svg viewBox="0 0 50 50"><rect x="3" y="7" width="27" height="35" rx="7" fill="#c8bde6" transform="rotate(-9 3 7)"/><rect x="22" y="6" width="25" height="35" rx="7" fill="#e9e3f5" stroke="#9180af" stroke-width="1.5"/><path d="m34 15 3 6 6 1-5 4 1 7-5-3-6 3 1-7-5-4 7-1z" fill="#ad99ce"/></svg>',check:'<svg viewBox="0 0 50 50" fill="none"><circle cx="25" cy="25" r="19" fill="#e8e9c5"/><path d="m15 25 7 7 14-16" stroke="#698359" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg>'};
async function home(){current=null;const examples=activeWords();const [events,sessions]=await Promise.all([all('events','profileId',profile.id),all('sessions','profileId',profile.id)]);const stats=summarize(events),remembered=Object.values(stats).filter(p=>p.lastCheck?.correct).length;const modes=[['learn','Learn words','Look, listen, and try it in your own voice.','5 minutes'],['guess','Guess which?','Listen carefully. Find the matching picture.','10 questions'],['memo','Memo','Turn the cards. Find a little matching pair.','4 × 4 cards'],['check','Check!','See which words you remember on the first try.','10 questions'],['sentences',currentTopic()?.presentation==='definition'?'Sentences in context':'What is happening?',currentTopic()?.presentation==='definition'?'Listen to a sentence. Choose its precise interpretation.':'Hear a sentence. Find the matching scene.',`${activeSentences().length} scenes · 10 questions`],['mixed','Mixed play','Objects and action scenes, all in one session.','10 questions'],['explore','Show me','Tap a picture. Hear its name. Explore at your own pace.','No questions · no scores']];frame(`${lessonPanel()}<section class="hero"><div><div class="eyebrow">A SMALL MOMENT. A BIG DISCOVERY.</div><h1>Little objects.<br><em>Growing words.</em></h1><p>See it. Hear it. Give it a try.<br>A playful place for ${escape(profile.name)} to find their first English words.</p></div><div class="hero-art" aria-hidden="true"><div class="art-orbit"></div><span class="spark">✦</span><div class="art-card a">${image(examples[0],'')}<span>${escape(examples[0].word)}</span></div><div class="art-card b">${image(examples[1],'')}<span>${escape(examples[1].word)}</span></div><div class="art-card c">${image(examples[2],'')}<span>${escape(examples[2].word)}</span></div><span class="art-note">SMALL THINGS, NEW POSSIBILITIES</span></div></section><div class="section-title"><h2>How shall we play?</h2><span>${activeWords().length} words · ${activeSentences().length} phrases · ${currentTopic()?escape(currentTopic().title):LEVELS.find(l=>l[0]===(profile.settings.difficulty||'everyday'))?.[1]||'Everyday'}</span></div><section class="mode-grid" aria-label="Learning modes">${modes.map(([id,title,desc,meta],i)=>`<button class="mode-card ${i===0?'featured':''}" data-mode="${id}"><span class="mode-symbol">${icons[id]}</span><h3>${title}</h3><p>${desc}</p><span class="mode-bottom">${meta}<span class="arrow">↗</span></span></button>`).join('')}</section><section class="home-bottom"><div class="daily"><span class="daily-icon">☀</span><div><h3>Five minutes is a lovely start.</h3><p>Explore five words, meet each one three times.<br>Little repeats make familiar friends.</p></div></div><div class="mini-stats"><div><strong>${Object.keys(stats).length}</strong><span>words & sentences explored</span></div><div><strong>${remembered}</strong><span>first-try check wins</span></div><div><strong>${sessions.filter(s=>s.completed).length}</strong><span>sessions finished</span></div></div></section>`);root.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>start(b.dataset.mode));bindLesson();}
async function start(mode){teardown();const startToken=epoch;if(!speech.ready){await say('Let’s play.',1);if(startToken!==epoch)return;}view=mode;const prior=await all('sessions','profileId',profile.id);const topic=currentTopic();await ensureTopicPictures(topic);const pool=mode==='sentences'?activeSentences():mode==='explore'?variedWords(activeExplore()):variedWords(activeWords());const offset=prior.filter(s=>s.mode===mode&&s.completed&&lessonSessionMatches(s,topic?.code)).length*(['learn','mixed'].includes(mode)?5:10)%pool.length;const session={id:uid(),profileId:profile.id,mode,lessonCode:topic?.code||'',startedAt:new Date().toISOString(),completed:false,endedAt:null,settings:{...profile.settings}};if(mode==='memo'){const last=prior.filter(s=>s.mode==='memo'&&lessonSessionMatches(s,topic?.code)).sort((a,b)=>b.startedAt.localeCompare(a.startedAt))[0];session.wordIds=memoWords(pool,last?.wordIds||[]).map(w=>w.id);}await put('sessions',session);current={session,mode,pool,events:[],round:0,attempt:0,answered:false,offset,started:performance.now(),paused:false,pauseTotal:0,pausedAt:0};if(mode==='learn'){current.plan=learnPlan(pool,offset);current.slot=-1;renderLearn();learnTick();interval=setInterval(learnTick,200);}else if(mode==='memo'){current.deck=shuffle(session.wordIds.map(id=>byId(id)).flatMap(w=>[{word:w,key:uid()},{word:w,key:uid()}]));current.open=[];current.matched=new Set();current.moves=0;current.busy=false;renderMemo();}else if(mode==='explore'){current.explorePage=0;current.exploreGroup='All';renderExplore();}else{if(mode==='mixed')current.plan=mixedPlan(pool,activeSentences(),offset);renderQuestion();}}
async function log(type,w,extra={}){if(!current)return;const e={id:uid(),profileId:profile.id,sessionId:current.session.id,mode:current.mode,lessonCode:current.session.lessonCode||'',type,wordId:w.id,at:new Date().toISOString(),...extra};current.events.push(e);try{await put('events',e);}catch{toast('Progress could not be saved. Export your progress from Settings.');}}
function activityTop(name,subtitle,badge){return `<div class="activity-top"><button class="back" id="end-session">← Finish</button><div class="activity-meta"><h1>${name}</h1><p>${subtitle}</p></div><span class="pill" id="activity-badge">${badge}</span></div>`;}
function bindFinish(){root.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));$('#end-session').onclick=()=>finishSession(false);}
function elapsed(){if(!current)return 0;return (current.paused?current.pausedAt:performance.now())-current.started-current.pauseTotal;}
function renderLearn(){frame(activityTop('Learn words','Five objects. Three friendly visits.','5:00')+`<section class="stage"><div class="eyebrow" id="learn-step">LISTEN · REPEAT · LISTEN TO YOU</div><div class="learn-card" id="learn-picture"></div><div class="word" id="learn-word"></div><div class="translation" id="learn-translation"></div><div class="visit-dots" id="visits"></div><p class="sub" id="learn-cue" aria-live="polite">Listen three times, then say it yourself.</p><div class="controls"><button class="secondary" id="learn-listen">◖)) Listen ×3</button><button class="primary" id="record">● Record my voice</button><button class="secondary" id="playback" disabled>▶ Play mine</button></div><p class="record-status" id="record-status">Your recording stays on this device and is cleared at the next picture.</p><div class="controls"><button class="secondary" id="pause-learn">Ⅱ Pause</button></div><div class="progress-bar"><span id="learn-progress"></span></div><p class="sub" id="slot-label" style="font-size:11px;margin-top:12px"></p></section>`);bindFinish();$('#learn-listen').onclick=()=>{if(!current.paused)learnSpeak();};$('#record').onclick=recordVoice;$('#playback').onclick=()=>playClip();$('#pause-learn').onclick=()=>{if(current.paused){current.pauseTotal+=performance.now()-current.pausedAt;current.paused=false;$('#pause-learn').textContent='Ⅱ Pause';$('#record').disabled=false;$('#learn-listen').disabled=false;learnSpeak();}else{current.paused=true;current.pausedAt=performance.now();cancelSpeech();stopMedia();$('#playback').disabled=true;$('#pause-learn').textContent='▶ Resume';$('#record').disabled=true;$('#learn-listen').disabled=true;$('#record').textContent='● Record my voice';$('#record').classList.remove('recording');$('#learn-cue').textContent='Paused. Take your time.';}};}
async function learnSpeak(){if(!current||current.mode!=='learn'||current.paused)return;const token=epoch,slot=current.slot,w=current.plan[slot];$('#learn-cue').textContent='Listen…';const ok=await say(w.word,3);if(token!==epoch||current?.slot!==slot||current?.paused)return;if(ok){$('#learn-cue').textContent='Your turn. Repeat the word!';await say('Repeat',1);}if(token===epoch&&current?.slot===slot&&!current.paused)$('#learn-cue').textContent='Tap Record my voice, say the word, then listen to yourself.';}
function learnTick(){if(!current||current.paused)return;const ms=elapsed();if(ms>=300000){finishSession(true);return;}const slot=Math.floor(ms/20000);const left=Math.ceil((300000-ms)/1000);$('#activity-badge').textContent=`${Math.floor(left/60)}:${String(left%60).padStart(2,'0')}`;$('#learn-progress').style.width=`${ms/3000}%`;$('#slot-label').textContent=`Picture ${slot+1} of 15 · next picture in ${Math.ceil((20000-ms%20000)/1000)}s`;if(slot!==current.slot){cancelSpeech();stopMedia();current.slot=slot;const w=current.plan[slot];$('#learn-picture').innerHTML=image(w);$('#learn-word').textContent=w.word;$('#learn-translation').textContent=w.meaning_pl;$('#visits').innerHTML=Array.from({length:3},(_,i)=>`<i class="${i<=Math.floor(slot/5)?'on':''}"></i>`).join('');$('#learn-step').textContent=`VISIT ${Math.floor(slot/5)+1} OF 3`;$('#record').textContent='● Record my voice';$('#record').disabled=false;$('#record').classList.remove('recording');$('#playback').disabled=true;$('#record-status').textContent='Your recording stays on this device and is cleared at the next picture.';log('exposure',w,{visit:Math.floor(slot/5)+1,position:slot});learnSpeak();}}
async function recordVoice(){if(recorder?.state==='recording'){recorder.stop();return;}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('Recording is not supported here. Open this app in a modern browser over HTTPS.');return;}cancelSpeech();clip?.pause();const token=epoch,slot=current.slot;$('#record').disabled=true;$('#record-status').textContent='Waiting for microphone permission…';try{const requested=await navigator.mediaDevices.getUserMedia({audio:true});if(token!==epoch||current?.slot!==slot||current?.paused){requested.getTracks().forEach(t=>t.stop());return;}stream=requested;const chunks=[];recorder=new MediaRecorder(stream);const local=recorder;local.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};local.onstop=()=>{clearTimeout(recordTimer);stream?.getTracks().forEach(t=>t.stop());stream=null;recorder=null;if(token!==epoch||current?.slot!==slot)return;if(clipURL)URL.revokeObjectURL(clipURL);const blob=new Blob(chunks,{type:local.mimeType||'audio/webm'});if(!blob.size){$('#record').textContent='● Record my voice';$('#record').classList.remove('recording');$('#record-status').textContent='No audio captured. Please try again.';toast('No audio captured. Please try again.');return;}clipURL=URL.createObjectURL(blob);clip=new Audio(clipURL);$('#record').textContent='● Record again';$('#record').classList.remove('recording');$('#playback').disabled=false;$('#record-status').textContent='Here is your voice. You can record again.';log('recording',current.plan[slot],{audioStored:false});playClip();};local.start();$('#record').disabled=false;$('#record').textContent='■ Stop recording';$('#record').classList.add('recording');$('#record-status').textContent='Listening… Say the word. Stops automatically after 5 seconds.';recordTimer=setTimeout(()=>{if(local.state==='recording')local.stop();},5000);}catch(e){if(token!==epoch||current?.slot!==slot)return;$('#record').disabled=false;$('#record-status').textContent='Microphone unavailable. You can still listen and repeat aloud.';toast(e.name==='NotAllowedError'?'Microphone permission was not granted. Enable it in your browser to record.':'No microphone could be opened. Check your browser and microphone.');}}
async function playClip(){if(!clip)return;cancelSpeech();clip.currentTime=0;try{await clip.play();}catch{toast('Tap Play mine to hear your recording.');}}
function target(){if(current.mode==='mixed')return current.plan[current.round];const pool=current.pool;return pool[(current.offset+current.round)%pool.length];}
function renderQuestion(){const w=target(),count=profile.settings.tiles,repeats=w.presentation==='definition'?1:3;current.options=w.person?(w.topicCode?optionsFor(activeSentences(),w,count,current.round):sentenceOptions(activeSentences(),w,count,current.offset+current.round)):optionsFor(current.pool,w,count,current.round);current.attempt=0;current.answered=false;current.roundAt=performance.now();frame(activityTop(current.mode==='mixed'?'Mixed play':current.mode==='sentences'?(w.presentation==='definition'?'Sentences in context':'What is happening?'):current.mode==='check'?'Check!':'Guess which?',w.presentation==='definition'?'Listen. Choose the most precise meaning.':current.mode==='check'?'Your first choice is what counts.':'Listen. Look. Choose a picture.',`${current.round+1} / 10`)+`<section class="stage"><div class="guess-heading"><button class="sound-btn" id="replay" aria-label="Listen again">◖))</button><div style="text-align:left"><h2>${w.presentation==='definition'?(w.kind==='sentence'?'Which interpretation?':'Which meaning?'):w.person?'Which scene?':'Which picture?'}</h2><p class="sub">Tap the speaker to hear it again.</p></div></div><div class="tiles ${w.person?'scene-choices':''} ${count>4?'many':''}" id="choices">${current.options.map((item,i)=>`<button class="tile" data-answer="${item.id}" aria-label="${item.presentation==='definition'?escape(item.gloss):'Picture '+(i+1)}">${image(item,'')}<span class="feedback-mark"></span></button>`).join('')}</div><div class="feedback" id="feedback" aria-live="polite"></div><div class="progress-bar"><span style="width:${current.round*10}%"></span></div></section>`);bindFinish();$('#replay').onclick=()=>say(w.word,repeats);root.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answer(b));say(w.word,repeats);}
async function answer(button){
 if(!current||current.answered||button.disabled)return;
 cancelSpeech();const s=current,token=epoch,w=target(),chosen=button.dataset.answer,automatic=['check','sentences','mixed'].includes(s.mode);
 s.attempt++;const correct=chosen===w.id,attempt=s.attempt;
 log('answer',w,{selectedWordId:chosen,correct,attempt,firstTry:attempt===1,latencyMs:Math.round(performance.now()-s.roundAt),tileCount:profile.settings.tiles,questionIndex:s.round});
 if(correct){
  s.answered=true;button.classList.add('correct');button.querySelector('.feedback-mark').textContent='✓';root.querySelectorAll('[data-answer]').forEach(b=>b.disabled=true);
  const message=s.mode==='check'?(attempt===1?'First try — remembered!':'Good practice. We’ll revisit this word.'):'You found it!';
  $('#feedback').innerHTML=`<span>${message} <strong>${escape(w.word)}</strong></span>${automatic?'':`<button class="primary" id="next-question">${s.round===9?'See results':'Next →'}</button>`}`;
  const next=()=>{if(token!==epoch||current!==s)return;cancelSpeech();s.round++;if(s.round===10)finishSession(true);else renderQuestion();};
  if(automatic){
   $('#replay').disabled=true;
   const spoken=await say(w.word,1);if(!spoken){if(token===epoch&&current===s){$('#replay').disabled=false;$('#replay').onclick=retrySound;}return;}await new Promise(r=>setTimeout(r,600));next();
  }else{$('#next-question').onclick=next;say(w.word,1);}
 }else{
  button.classList.add('wrong');button.disabled=true;button.querySelector('.feedback-mark').textContent='↻';
  $('#feedback').textContent=automatic?'Not this one. Listen to the picture you chose, then tap the speaker to hear the question again.':'Not this one. Listen and try another picture.';
  if(automatic){const selected=byId(chosen);if(selected)await say(selected.word,1);}
 }
}
function renderExplore(){
 const s=current,group=s.exploreGroup,items=s.pool.filter(w=>group==='All'||pictureGroup(w)===group),pages=Math.max(1,Math.ceil(items.length/12));s.explorePage=Math.min(s.explorePage,pages-1);const shown=items.slice(s.explorePage*12,s.explorePage*12+12);
 frame(activityTop('Show me','Tap any picture to hear its name. No questions, no scores.',`${s.explorePage+1} / ${pages}`)+`<section class="stage"><div class="controls explore-filters" aria-label="Picture groups">${['All',...new Set(s.pool.map(pictureGroup))].map(name=>`<button class="secondary" data-group="${escape(name)}" aria-pressed="${name===group}">${escape(name)}</button>`).join('')}</div><div class="explore-grid">${shown.map(w=>`<button class="explore-card" data-explore="${w.id}" aria-label="Listen: ${escape(w.word)}">${image(w,'')}<strong>${escape(w.word)}</strong></button>`).join('')}</div><p id="explore-speaking" class="sub" aria-live="polite">Pick something you like.</p><div class="controls"><button class="secondary" id="explore-prev" ${s.explorePage===0?'disabled':''}>← Previous</button><button class="secondary" id="explore-next" ${s.explorePage===pages-1?'disabled':''}>More pictures →</button></div></section>`);bindFinish();
 root.querySelectorAll('[data-explore]').forEach(b=>b.onclick=()=>{const w=byId(b.dataset.explore);$('#explore-speaking').textContent=w.word+' · '+w.meaning_pl;say(w.word,2);log('exposure',w);});
 root.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>{cancelSpeech();s.exploreGroup=b.dataset.group;s.explorePage=0;renderExplore();});
 $('#explore-prev').onclick=()=>{cancelSpeech();s.explorePage--;renderExplore();};$('#explore-next').onclick=()=>{cancelSpeech();s.explorePage++;renderExplore();};
}
function renderMemo(){frame(activityTop('Memo','Turn a card. Listen. Find its friend.','0 / 8 pairs')+`<section class="stage"><p class="sub">Each card says its name twice. Find a pair for a little celebration.</p><div class="memory ${current.session.lessonCode?'lesson-memory':''}" id="memory-board">${current.deck.map((card,i)=>`<button class="mem-card" data-card="${i}" aria-label="Face-down card ${i+1}"><span>✳</span></button>`).join('')}</div><div class="feedback" id="memo-message" aria-live="polite">Pick any card to begin.</div><p class="sub" id="memo-moves">0 turns</p></section>`);bindFinish();root.querySelectorAll('[data-card]').forEach(b=>b.onclick=()=>flip(Number(b.dataset.card)));}
async function flip(i){if(!current||current.busy||current.matched.has(i)||current.open.includes(i))return;const token=epoch,s=current,card=s.deck[i],b=$(`[data-card="${i}"]`);s.busy=true;s.open.push(i);b.classList.add('revealed');b.innerHTML=image(card.word,'');b.setAttribute('aria-label',`Revealed ${card.word.word}`);$('#memo-message').textContent='Listen…';root.querySelectorAll('[data-card]').forEach(b=>b.disabled=true);await log('exposure',card.word,{position:i});if(token!==epoch||current!==s)return;await say(card.word.word,2);if(token!==epoch||current!==s)return;if(s.open.length===2){s.moves++;$('#memo-moves').textContent=`${s.moves} turns`;const [a,c]=s.open;const match=s.deck[a].word.id===s.deck[c].word.id;await log('memory_turn',card.word,{correct:match,turn:s.moves,otherWordId:s.deck[a].word.id});if(match){s.matched.add(a);s.matched.add(c);[a,c].forEach(j=>$(`[data-card="${j}"]`).classList.add('matched'));const celebration=pairCelebration(card.word.word,lastCelebration);lastCelebration=celebration.index;$('#memo-message').textContent=celebration.text;$('#activity-badge').textContent=`${s.matched.size/2} / 8 pairs`;await say(celebration.text,1);if(token!==epoch||current!==s)return;}else{$('#memo-message').textContent='Two different objects. Remember where they are.';await new Promise(r=>setTimeout(r,900));if(token!==epoch||current!==s)return;[a,c].forEach(j=>{const el=$(`[data-card="${j}"]`);el.classList.remove('revealed');el.innerHTML='<span>✳</span>';el.setAttribute('aria-label',`Face-down card ${j+1}`);});}s.open=[];if(s.matched.size===16){await finishSession(true);return;}}else $('#memo-message').textContent='Now choose another card.';if(token!==epoch||current!==s)return;s.busy=false;root.querySelectorAll('[data-card]').forEach(b=>b.disabled=s.matched.has(Number(b.dataset.card))||s.open.includes(Number(b.dataset.card)));}
async function finishSession(completed){if(!current)return;const s=current;const duration=Math.round(elapsed()/1000);teardown();current=null;view='summary';s.session.endedAt=new Date().toISOString();s.session.completed=completed;s.session.durationSeconds=duration;s.session.eventCount=s.events.length;try{await put('sessions',s.session);}catch{toast('This session could not be saved.');}const r=checkReport(s.events),first=s.events.filter(e=>e.type==='answer'&&e.attempt===1),exposures=s.events.filter(e=>e.type==='exposure'),distinct=new Set(exposures.map(e=>e.wordId));let content='';if(s.mode==='explore'){content=`<div class="summary-stats"><div><strong>${distinct.size}</strong><span>pictures explored</span></div><div><strong>${exposures.length}</strong><span>picture taps</span></div></div><p class="sub">A little listening and discovering, at your own pace.</p>`;}else if(s.mode==='check'){content=`<div class="summary-stats"><div><strong>${r.remembered.length}</strong><span>remembered first try</span></div><div><strong>${r.practice.length}</strong><span>to practise</span></div><div><strong>${r.total}</strong><span>words checked</span></div></div><div class="report-grid"><div class="report-col"><h3>✓ Remembered</h3>${r.remembered.map(e=>`<div class="word-chip">${image(byId(e.wordId),'')} ${escape(byId(e.wordId).word)}</div>`).join('')||'<p class="sub">No first-try wins in this check yet.</p>'}</div><div class="report-col"><h3>↻ Let’s revisit</h3>${r.practice.map(e=>`<div class="word-chip">${image(byId(e.wordId),'')} ${escape(byId(e.wordId).word)}</div>`).join('')||'<p class="sub">No missed first choices.</p>'}</div></div><p class="sub">This is a snapshot of this check, not a permanent mastery score.</p>`;}else if(s.mode==='learn'){content=`<div class="summary-stats"><div><strong>${distinct.size}</strong><span>objects explored</span></div><div><strong>${exposures.length}</strong><span>picture visits</span></div><div><strong>${s.events.filter(e=>e.type==='recording').length}</strong><span>voice recordings</span></div></div><div class="session-words">${[...distinct].map(id=>image(byId(id))).join('')}</div><p class="sub">${completed?'Five words, three visits each. Lovely work.':'You can start another little session whenever you like.'}</p>`;}else if(s.mode==='memo'){content=`<div class="summary-stats"><div><strong>${s.matched.size/2}</strong><span>pairs found</span></div><div><strong>${s.moves}</strong><span>turns</span></div></div><p class="sub">Every turn is another chance to hear a word.</p>`;}else content=`<div class="summary-stats"><div><strong>${first.filter(e=>e.correct).length}</strong><span>first-try wins</span></div><div><strong>${first.length}</strong><span>${s.mode==='mixed'?'items':s.mode==='sentences'?'sentences':'words'} tried</span></div></div><p class="sub">Your attempts are saved. Every little try matters.</p>`;frame(`<section class="stage summary"><div class="eyebrow">${completed?'SESSION COMPLETE':'SESSION SAVED'}</div><div class="summary-icon">✦</div><h1>${completed?'A little more familiar.':'A lovely little start.'}</h1><p class="sub">${escape(profile.name)}’s ${s.mode==='check'?'word check':'play time'} · ${Math.floor(duration/60)}m ${duration%60}s</p>${content}<div class="controls"><button class="primary" id="play-again">Play again</button><button class="secondary" data-nav="home">Back to home</button><button class="secondary" data-nav="progress">View progress</button></div></section>`);$('#play-again').onclick=()=>start(s.mode);}
function settings(){const available=window.speechSynthesis?.getVoices().filter(v=>v.lang.startsWith('en'))??[];frame(`<section class="settings"><button class="back" data-nav="home">← Back to play</button><h1 style="margin-top:24px">For the grown-ups.</h1><p class="sub">A few little settings, just right for your learner.</p><div class="settings-section"><h2>Who’s learning?</h2><div class="profile-list">${profiles.map(p=>`<button class="profile-option ${p.id===profile.id?'selected':''}" data-profile="${p.id}">${escape(p.name)}${p.id===profile.id?' ✓':''}</button>`).join('')}</div><form class="add-profile" id="profile-form"><input id="new-profile" maxlength="30" placeholder="New learner’s nickname" aria-label="New learner nickname" required><button class="primary" type="submit">Add</button></form><p class="sub" style="font-size:12px;margin-top:13px">Profiles and progress are separate. No email or real name needed.</p></div><div class="settings-section"><h2>Learning level</h2><div class="setting-row"><label for="difficulty">Word set<small>${currentTopic()?'The active lesson controls vocabulary. Leave it on the home page to change word sets.':'Start small, then explore more. Applies to word games and Show me.'}</small></label><select id="difficulty" ${currentTopic()?'disabled':''}>${LEVELS.map(([id,name,description])=>`<option value="${id}" ${(profile.settings.difficulty||'everyday')===id?'selected':''}>${name}</option>`).join('')}</select></div><p class="sub" style="font-size:12px">First words: 40 familiar items. Everyday: common animals, food, vehicles and household objects. Challenge: the full dictionary, including instruments and less common animals.</p><h2 style="margin-top:24px">Listening & pictures</h2><div class="setting-row"><label for="tiles">Picture choices<small>Used in Guess which?, Check!, Situations and Mixed play</small></label><select id="tiles">${[2,4,6,8].map(n=>`<option ${profile.settings.tiles===n?'selected':''} value="${n}">${n} pictures</option>`).join('')}</select></div><div class="setting-row"><label for="voice">English voice<small>Voices are supplied by your device.</small></label><select id="voice"><option value="">Automatic English</option>${available.map(v=>`<option value="${escape(v.voiceURI)}" ${profile.settings.voice===v.voiceURI?'selected':''}>${escape(v.name)} (${v.lang})</option>`).join('')}</select></div><div class="setting-row"><label for="rate">Speaking speed</label><select id="rate">${[[.65,'Gentle'],[.8,'Normal'],[1,'Natural']].map(([n,t])=>`<option value="${n}" ${profile.settings.rate===n?'selected':''}>${t}</option>`).join('')}</select></div><button class="secondary" id="test-voice">◖)) Test voice: apple</button><p class="sub" style="font-size:12px;margin-top:12px">No sound? Use Enable sound, check media volume and headphones, or try this page in your phone’s browser. Some devices need an English text-to-speech voice installed in system settings.</p></div><div class="settings-section"><h2>Your progress belongs to you.</h2><p class="sub" style="font-size:13px">Progress is saved in a database in this browser, separately for each learner. It does not sync between devices. Clearing browser data removes it; export a backup to keep it.</p><div class="controls" style="justify-content:flex-start"><button class="secondary" id="export">↓ Export this learner</button></div><p class="sub" style="font-size:12px">Voice recordings are temporary, played locally, and never included in progress backups. Pronunciation is not scored.</p></div><p class="sub" style="font-size:13px"><a href="audit.html">View all ${words.length} object pictures</a> · <a href="sentences-audit.html">View all ${sentences.length} sentence pictures</a> · <a href="credits.html">Picture credits & licenses</a></p><div class="notice">Microphone access is requested only when Record my voice is pressed. If your browser asks, allow it to record. You can learn without recording, too.</div></section>`);root.querySelectorAll('[data-profile]').forEach(b=>b.onclick=async()=>{profile=profiles.find(p=>p.id===b.dataset.profile);localStorage.setItem('little-active',profile.id);cancelSpeech();settings();});$('#profile-form').onsubmit=async e=>{e.preventDefault();const name=$('#new-profile').value.trim();if(!name)return;const p={id:uid(),name,createdAt:new Date().toISOString(),settings:{tiles:4,rate:.8,voice:''}};await put('profiles',p);profiles.push(p);profile=p;localStorage.setItem('little-active',p.id);settings();toast('New learner added.');};for(const field of ['tiles','voice','rate','difficulty'])$('#'+field).onchange=async e=>{profile.settings[field]=['voice','difficulty'].includes(field)?e.target.value:Number(e.target.value);await put('profiles',profile);toast('Setting saved.');};$('#test-voice').onclick=()=>say('apple',3);$('#export').onclick=exportProfile;}
async function exportProfile(){const payload={schemaVersion:1,exportedAt:new Date().toISOString(),profile,sessions:await all('sessions','profileId',profile.id),events:await all('events','profileId',profile.id),vocabularyVersion:'objects-323-sentences-50-v2',vocabulary:words,sentences,lesson:currentTopic()};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='little-objects-progress-'+profile.id.slice(0,8)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Progress backup downloaded.');}
async function progress(){const [events,sessions]=await Promise.all([all('events','profileId',profile.id),all('sessions','profileId',profile.id)]);const stats=summarize(events),explored=(currentTopic()?.entries||[...words,...sentences]).filter(w=>stats[w.id]);frame(`<section class="progress-page"><button class="back" data-nav="home">← Back to play</button><h1 style="margin-top:24px">Little steps, saved.</h1><p class="sub">${escape(profile.name)}’s own learning story.</p><div class="summary-stats"><div><strong>${explored.length}</strong><span>words & sentences explored</span></div><div><strong>${Object.values(stats).filter(s=>s.lastCheck?.correct).length}</strong><span>latest check: first try</span></div><div><strong>${sessions.filter(s=>s.completed).length}</strong><span>finished sessions</span></div></div><div class="table-wrap">${explored.length?`<table><thead><tr><th>Word / sentence</th><th>Picture visits</th><th>First-try answers</th><th>Latest Check!</th></tr></thead><tbody>${explored.map(w=>{const s=stats[w.id];return `<tr><td>${image(w,'')}${escape(w.word)}</td><td>${s.seen}</td><td>${s.firstCorrect} / ${s.firstCorrect+s.firstWrong}</td><td>${s.lastCheck?`<span class="status ${s.lastCheck.correct?'yes':'no'}">${s.lastCheck.correct?'Remembered':'Practise again'}</span>`:'<span class="sub" style="font-size:12px">Not checked</span>'}</td></tr>`;}).join('')}</tbody></table>`:'<div class="empty">A fresh little beginning. Play a mode to start your learning story.</div>'}</div><p class="sub" style="font-size:12px">First-try answers include Guess which? and Check! The latest-check label uses Check! only. Every attempt is kept in the event history.</p><div class="section-title" style="margin-top:30px"><h2>Recent play time</h2></div><div class="table-wrap">${sessions.length?`<table><thead><tr><th>Mode</th><th>When</th><th>Status</th></tr></thead><tbody>${sessions.sort((a,b)=>b.startedAt.localeCompare(a.startedAt)).slice(0,10).map(s=>`<tr><td>${({learn:'Learn words',guess:'Guess which?',memo:'Memo',check:'Check!',sentences:'What is happening?',mixed:'Mixed play',explore:'Show me'})[s.mode]}</td><td>${new Date(s.startedAt).toLocaleString()}</td><td>${s.completed?'Finished':s.endedAt?'Ended early':'Interrupted'}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No sessions yet.</div>'}</div></section>`);}
async function boot(){try{await openDB();[words,sentences,topics]=await Promise.all(['words.json','sentences.json','topics.json'].map(async path=>{const r=await fetch(path,{cache:'no-cache'});if(!r.ok)throw new Error('Content unavailable');return r.json();}));root.innerHTML='<p class="loading" role="status">Getting your pictures ready… <span id="picture-load">0</span></p>';pictureMemory=await preparePictures([...words,...sentences],(done,total)=>{const status=$('#picture-load');if(status)status.textContent=done+' / '+total;});profiles=await all('profiles');if(!profiles.length){profile={id:uid(),name:'Little learner',createdAt:new Date().toISOString(),settings:{tiles:4,rate:.8,voice:''}};await put('profiles',profile);profiles=[profile];}profile=profiles.find(p=>p.id===localStorage.getItem('little-active'))||profiles[0];await ensureTopicPictures(currentTopic());await home();}catch(e){root.innerHTML=`<main class="shell"><h1>We couldn’t open your learning space.</h1><p class="sub" style="margin:20px 0">Please check your connection, allow browser storage, and reload. Pictures must finish loading before play starts.</p><button class="primary" onclick="location.reload()">Try again</button></main>`;console.error(e);}}
window.addEventListener('pagehide',()=>{if(current){current.session.endedAt=new Date().toISOString();current.session.completed=false;put('sessions',current.session).catch(()=>{});}teardown();});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&view==='learn'&&current&&!current.paused)$('#pause-learn')?.click();});
if('speechSynthesis' in window)speechSynthesis.addEventListener('voiceschanged',()=>{const el=$('#voice');if(view!=='settings'||!el)return;const available=speechSynthesis.getVoices().filter(v=>v.lang.startsWith('en'));el.innerHTML='<option value="">Automatic English</option>'+available.map(v=>`<option value="${escape(v.voiceURI)}" ${profile.settings.voice===v.voiceURI?'selected':''}>${escape(v.name)} (${v.lang})</option>`).join('');});
boot();
